package com.randbox.randombox.client;
import com.randbox.randombox.network.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class EditorScreen extends Screen {private EditBox table,item,weight;private EditorScreen(){super(Component.translatable("randombox.editor"));}public static void open(){Minecraft.getInstance().setScreen(new EditorScreen());}
 @Override protected void init(){int x=width/2-110;table=new EditBox(font,x,60,220,20,Component.literal("Table"));table.setValue("minecraft:chests/simple_dungeon");item=new EditBox(font,x,90,220,20,Component.literal("Item"));item.setValue("minecraft:diamond");weight=new EditBox(font,x,120,220,20,Component.literal("Weight"));weight.setValue("1");addRenderableWidget(table);addRenderableWidget(item);addRenderableWidget(weight);addRenderableWidget(Button.builder(Component.translatable("randombox.save"),b->{int w;try{w=Integer.parseInt(weight.getValue());}catch(Exception e){w=1;}Net.CHANNEL.sendToServer(new SaveEntryPacket(table.getValue(),item.getValue(),w));b.setMessage(Component.literal("Saved ✓"));}).bounds(x,155,220,20).build());}
 @Override public void render(GuiGraphics g,int mx,int my,float p){renderBackground(g);g.drawCenteredString(font,title,width/2,25,0xFFFFFF);g.drawString(font,"Loot table ID",width/2-110,49,0xAAAAAA);g.drawString(font,"Item ID",width/2-110,79,0xAAAAAA);g.drawString(font,"Weight",width/2-110,109,0xAAAAAA);super.render(g,mx,my,p);}}
